extra_path_check.script:
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { nativeInstalledLayout } from './e2e/fixtures/collaboration-installed-layout.mjs';
const names=['literal%20','literal%2F','trailing%','space and #hash?query','中文 %25 #?'];
const result=[];
for (const platform of ['win32','darwin']) for(const name of names){
 const executable=platform==='win32'?`c:\\${name}\\installed\\Multica.exe`:`/task/${name}/Multica Candidate.app/Contents/MacOS/Multica`;
 const layout=nativeInstalledLayout(executable,platform);
 const expected=(platform==='win32'?path.win32:path.posix).join(layout.asar,'out','renderer','index.html');
 assert.equal(fileURLToPath(layout.rendererUrl,{windows:platform==='win32'}),expected);
 assert.equal(new URL(layout.rendererUrl).hash,'');assert.equal(new URL(layout.rendererUrl).search,'');
 result.push({platform,name,renderer:layout.rendererUrl,round_trip:true});
}
console.log(JSON.stringify({node:process.version,cases:result}));
